uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float intensity : 0.0 .. 2.0 = 1.0;
uniform vec3 tint : color = 1.0, 0.45, 0.12;

state fixed phase;
state fixed flick;
state fixed sparkH;
state fixed sparkR;
state fixed sparkA;
state fixed sparkV;
state fixed sparkLife;
state fixed sparkAge;
state fixed sparkGlow;
state fixed8 heat[500];
state bool inited;

void update() {
  phase = fract(phase + fixed(dt) * fixed(0.15) * fixed(speed));
  flick = fract(flick + fixed(dt) * fixed(speed));

  fixed age = sparkAge + fixed(dt);
  fixed life = sparkLife;
  fixed g = fixed(0.0);
  if (age < life) {
    g = fixed(1.0) - age / life;
    g = g * g;
    sparkAge = age;
  } else {
    fixed r = hash(float(frame) * 0.173);
    if (r < fixed(0.05)) {
      sparkH = fixed(0.15) + fixed(0.85) * hash(float(frame) * 0.311 + 1.0);
      sparkR = hash(float(frame) * 0.577 + 2.0);
      sparkA = hash(float(frame) * 0.719 + 3.0);
      sparkV = fixed(0.25) + fixed(0.55) * hash(float(frame) * 0.911 + 4.0);
      sparkLife = fixed(0.4) + fixed(0.8) * hash(float(frame) * 0.417 + 5.0);
      sparkAge = fixed(0.0);
      g = fixed(1.0);
    }
  }
  sparkGlow = g;

  fixed hgt = fract(phase + fixed(0.5));
  fixed rise = fixed(1.0) - hgt;
  for (int i = 0; i < 500; i = i + 1) {
    fixed y = fixed(led.pos.y) * fixed(3.333);
    fixed n = hash(float(i) * 0.011 + float(frame >> 5) * 0.37);
    fixed e = heat[i] * fixed(0.94);
    e = e + n * n * fixed(0.06) * rise * (fixed(1.0) - y);
    if (e > fixed(1.0)) e = fixed(1.0);
    heat[i] = fixed8(e);
  }
}

vec3 shade(Led led) {
  fixed y = fixed(led.pos.y) * fixed(3.333);
  fixed e = fixed(heat[led.idx]);

  fixed fl = fixed(0.75) + fixed(0.25) * sin(flick * fixed(6.0) + fixed(led.idx) * fixed(0.7));
  fixed ember = e * fl * (fixed(1.0) - y * fixed(0.5));
  ember = ember * ember;

  fixed h = sparkH;
  fixed rr = sparkR;
  fixed aa = sparkA;
  fixed vy = sparkV;
  fixed age = sparkAge;
  fixed px = fixed(led.uv.x) - fixed(0.5);
  fixed py = fixed(led.uv.y) - fixed(0.5);
  fixed dx = px * cos(aa * fixed(6.2832)) + py * sin(aa * fixed(6.2832));
  fixed dy = py * cos(aa * fixed(6.2832)) - px * sin(aa * fixed(6.2832));
  fixed sx = dx - rr * fixed(0.5);
  fixed sy = dy - (h - vy * age);
  fixed sd = sx * sx + sy * sy;
  fixed spark = sparkGlow * (fixed(1.0) - clamp(sd * fixed(400.0), fixed(0.0), fixed(1.0)));

  fixed v = ember + spark;
  if (v > fixed(1.0)) v = fixed(1.0);
  vec3 col = hsv2rgb(tint.x + fixed(0.02) * (fixed(1.0) - y), fixed(0.85), v * fixed(intensity));
  return col;
}

